#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    using namespace std;

    int N;
    cin >> N;
    unsigned long L, R;
    cin >> L >> R;
    --L;
    --R;

    // 基底をつくる
    vector<unsigned long> basis;
    for (int i = 0; i < N; ++i) {
        unsigned long A;
        cin >> A;
        for (auto b : basis)
            if ((A ^ b) < A)
                A ^= b;
        for (auto &&b : basis)
            if ((A ^ b) < b)
                b ^= A;
        if (A)
            basis.emplace_back(A);
    }

    // 昇順に並べる
    sort(begin(basis), end(basis));

    // L 番目の値を得る
    unsigned long ans{};
    for (int i = 0; i < 60; ++i)
        if (L >> i & 1)
            ans ^= basis[i];

    for (int i = 1; i < size(basis); ++i)
        basis[i] ^= basis[i - 1];

    // L 番目から R 番目までの値を出力
    cout << ans;
    for (unsigned long x{L}; x < R; ++x) {
        ans ^= basis[__builtin_popcountl(x ^ (x + 1)) - 1]; // 差分を更新
        cout << " " << ans;
    }
    cout << endl;

    return 0;
}
